mapper.select:
SELECT id, cart_id, product_id, quantity, created_at, updated_at
FROM cart_items
WHERE cart_id = #{cartId}
  AND product_id = #{productId}

SELECT id, cart_id, product_id, quantity, created_at, updated_at
FROM cart_items
WHERE id = #{cartItemId}
  AND cart_id = #{cartId}

